namespace TypeSafeAI.Tests;

/// <summary>
/// The request and response bodies printed verbatim in the TypeSafe documentation.
/// </summary>
/// <remarks>
/// These are transcribed from the docs rather than generated by the SDK, so that the serialization
/// tests compare the SDK against the published contract instead of against itself.
/// </remarks>
internal static class Fixtures
{
    /// <summary>The minimal noul request from the API reference.</summary>
    public const string MinimalNoulRequest = """
        {
          "state": "Help! My payouts have been failing for 3 days.",
          "model": "jev-latest",
          "questions": {
            "is_urgent": {
              "type": "noul",
              "instructions": "Does this convey urgency?"
            }
          }
        }
        """;

    /// <summary>The noul request with criteria from the API reference.</summary>
    public const string NoulWithCriteriaRequest = """
        {
          "state": "Help! My payouts have been failing for 3 days.",
          "model": "jev-latest",
          "questions": {
            "is_urgent": {
              "type": "noul",
              "instructions": "Does this convey urgency?",
              "criteria": {
                "true": "Explicitly time-sensitive",
                "false": "No urgency expressed"
              }
            }
          }
        }
        """;

    /// <summary>The choice request from the API reference.</summary>
    public const string ChoiceRequest = """
        {
          "state": "Help! My payouts have been failing for 3 days.",
          "model": "jev-latest",
          "questions": {
            "department": {
              "type": "choice",
              "instructions": "Which team should handle this?",
              "criteria": {
                "billing": "Payments, invoicing, refunds",
                "technical": "Bugs, outages, integrations",
                "sales": "Pricing, upgrades, new accounts"
              }
            }
          }
        }
        """;

    /// <summary>The score request from the API reference.</summary>
    public const string ScoreRequest = """
        {
          "state": "Help! My payouts have been failing for 3 days.",
          "model": "jev-latest",
          "questions": {
            "frustration": {
              "type": "score",
              "instructions": "How frustrated is the customer?",
              "criteria": ["Calm", "Frustrated", "Very angry"]
            }
          }
        }
        """;

    /// <summary>The noul response from the API reference.</summary>
    public const string NoulResponse = """
        {
          "model": "jev-latest",
          "answers": {
            "is_urgent": {
              "type": "noul",
              "noul": 0.92
            }
