              "probabilities": { "billing": 0.08, "technical": 0.85, "sales": 0.07 },
              "confidence": 0.82
            }
          },
          "usage": { "input_tokens": 312, "output_tokens": 48 }
        }
        """;

    /// <summary>The score response from the API reference.</summary>
    public const string ScoreResponse = """
        {
          "model": "jev-latest",
          "answers": {
            "frustration": {
              "type": "score",
              "score": 1.6,
