          },
          "usage": { "input_tokens": 100, "output_tokens": 20 }
        }
        """;

    /// <summary>An error body for an application-level failure.</summary>
    public const string ApplicationErrorBody = """
        {"detail":{"error_type":"authentication_error","message":"Cannot authenticate with the server. Please check your API key and try again."}}
        """;

    /// <summary>An error body for a framework-level failure, where <c>detail</c> is a bare string.</summary>
    public const string FrameworkErrorBody = """{"detail":"Not Found"}""";

    /// <summary>An error body that is not JSON at all.</summary>
    public const string NonJsonErrorBody = "<html><body>502 Bad Gateway</body></html>";
